def semver_sort(versions):
    def parse_version(version):
        # Split into core version and build metadata
        if '+' in version:
            core, build = version.split('+', 1)
        else:
            core = version

        # Split into version numbers and pre-release
        if '-' in core:
            version_part, prerelease = core.split('-', 1)
        else:
            version_part = core
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = version_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # pre1 or pre2 can be None
        # A version with pre-release sorts before the same version without one
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release sorts after
        if pre2 is None:
            return -1  # version with pre-release sorts before

        # Compare pre-release identifiers
        for i in range(max(len(pre1), len(pre2))):
            if i >= len(pre1):
                return -1  # fewer identifiers sorts first
            if i >= len(pre2):
                return 1

            id1 = pre1[i]
            id2 = pre2[i]

            is_digit1 = id1.isdigit()
            is_digit2 = id2.isdigit()

            if is_digit1 and is_digit2:
                num1 = int(id1)
                num2 = int(id2)
                if num1 != num2:
                    return -1 if num1 < num2 else 1
            elif is_digit1:
                return -1  # all-digit identifier sorts before any other
            elif is_digit2:
                return 1
            else:
                if id1 != id2:
                    return -1 if id1 < id2 else 1

        return 0

    def sort_key(item):
        version, original_index = item
        major, minor, patch, prerelease = parse_version(version)

        # Convert prerelease to comparable tuple for sorting
        if prerelease is None:
            prerelease_key = (1,)  # sorts after versions with pre-release
        else:
            prerelease_key = (0,) + tuple(prerelease)

        # For proper comparison of prerelease identifiers
        def make_comparable(identifiers):
            result = []
            for ident in identifiers:
                if ident.isdigit():
                    result.append((0, int(ident)))  # numeric sorts first
                else:
                    result.append((1, ident))  # then lexical
            return result

        if prerelease is None:
            return (major, minor, patch, (1,), original_index)
        else:
            return (major, minor, patch, (0,) + tuple(make_comparable(prerelease)), original_index)

    # Add original index to maintain stable sort
    indexed_versions = [(v, i) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)

    return [v for v, _ in sorted_versions]

